dashboard.definition:
{
	"title": "FOCUS Example Usecase(s)",
	"description": "This view showcases example use cases with limited filtering options. It has been tested with sample data, so the underlying searches may not be fully accurate or valid.",
	"inputs": {
		"input_global_trp": {
			"options": {
				"defaultValue": "@mon,now",
				"token": "global_time"
			},
			"title": "Global Time Range",
			"type": "input.timerange"
		},
		"input_u6FJXHuo": {
			"dataSources": {
				"primary": "ds_J4evhrdt"
			},
			"options": {
				"backgroundColor": "#000000",
				"defaultValue": "*",
				"items": [
					{
						"label": "All",
						"value": "*"
					}
				],
				"token": "ProviderName"
			},
			"title": "Provider Name",
			"type": "input.dropdown"
		}
	},
	"defaults": {
		"dataSources": {
			"ds.search": {
				"options": {
					"queryParameters": {
						"earliest": "$global_time.earliest$",
						"latest": "$global_time.latest$"
					}
				}
			}
		}
	},
	"visualizations": {
		"viz_01SUTREb": {
			"options": {
				"preserveAspectRatio": true,
				"src": "/static/app/vhc_TA_focus/Capabilities/Architecting-for-Cloud.svg"
			},
			"type": "splunk.image"
		},
		"viz_0GudEw8Q": {
			"context": {
				"TotalBilledCostColumnFormatEditorConfig": {
					"number": {
						"precision": 4,
						"thousandSeparated": false,
						"unitPosition": "after"
					}
				},
				"TotalBilledCostRowColorsEditorConfig": [
					{
						"to": 20,
						"value": "#118832"
					},
					{
						"from": 20,
						"to": 40,
						"value": "#669922"
					},
					{
						"from": 40,
						"to": 60,
						"value": "#CBA700"
					},
					{
						"from": 60,
						"to": 80,
						"value": "#D94E17"
					},
					{
						"from": 80,
						"value": "#D41F1F"
					}
				]
			},
			"cornerRadius": [
				10,
				10,
				10,
				10
			],
			"dataSources": {
				"primary": "ds_yT4i6GXs"
			},
			"options": {
				"columnFormat": {
					"TotalBilledCost": {
						"align": "auto",
						"data": "> table | seriesByName(\"TotalBilledCost\") | formatByType(TotalBilledCostColumnFormatEditorConfig)",
						"headerAlign": "auto",
						"rowColors": "> table | seriesByName(\"TotalBilledCost\") | rangeValue(TotalBilledCostRowColorsEditorConfig)",
						"textOverflow": "break-word"
					}
				},
				"backgroundColor": "#192630",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)",
					"headerBackgroundColor": "> backgroundColor | setColorChannel(tableHeaderBackgroundColorConfig)",
					"rowColors": "> rowBackgroundColors | maxContrast(tableRowColorMaxContrast)",
					"headerColor": "> headerBackgroundColor | maxContrast(tableRowColorMaxContrast)"
				}
			},
			"type": "splunk.table"
		},
		"viz_0hhk3sJr": {
			"options": {
				"preserveAspectRatio": true,
				"src": "/static/app/vhc_TA_focus/Capabilities/Workload-Optimization-2.svg"
			},
			"type": "splunk.image"
		},
		"viz_1XpiMv2U": {
			"cornerRadius": [
				10,
				10,
				10,
				10
			],
			"options": {
				"backgroundColor": "#fbf4ff",
				"fontColor": "#000000",
				"fontFamily": "Helvetica",
				"markdown": "# Analyze costs by service name\n`#Allocation`  `#Reporting & Analytics` `#Forecasting`  `#Workload Optimization` `#Architecting for Cloud`  `#Onboarding Workload` `#Anomaly Management` `#Rate Optimization`\n### Context\n**Analyzing service-level spending trends** over a time period can expose expected and unexpected growth in the consumption of a cloud service, and **is a good way **for the FinOps team **to prioritize usage and rate optimization conversations** with product, engineering, and finance leaders within the organization.\n### FOCUS Columns\n\n- Billed Cost \n- Billing Period Start \n- Provider \n- Service Name \n- Sub Account ID \n- Sub Account Name \n- Effective Cost"
			},
			"type": "splunk.markdown"
		},
		"viz_2VmNIjcT": {
			"options": {
				"preserveAspectRatio": true,
