	"dataSources": {
		"ds_3rdJTQvt": {
			"name": "Donut - Report spending across billing periods for a provider by service category 2",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| search ProviderName = $ProviderName$\n| stats sum(sumBilledCost) AS TotalBilledCost BY ServiceCategory\n| sort -TotalBilledCost"
			},
			"type": "ds.chain"
		},
		"ds_50JCI5Ie": {
			"name": "Table - Report refunds in a billing period",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| search ProviderName = \"$ProviderName$\" ChargeCategory = \"Correction\" \n| stats sum(sumBilledCost) AS TotalBilledCost BY ProviderName, BillingAccountId, ChargeCategory, ServiceCategory, ServiceName"
			},
			"type": "ds.chain"
		},
		"ds_8RbrxgxJ": {
			"name": "Table - Analyze costs by service name",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| stats sum(sumBilledCost) AS TotalBilledCost,\n    sum(sumEffectiveCost) AS TotalEffectiveCost \n    BY BillingPeriodStart, ProviderName, SubAccountId, SubAccountName, ServiceName \n| sort -TotalBilledCost"
			},
			"type": "ds.chain"
		},
		"ds_AO0CCqsg": {
			"name": "Table - Report commitment discount purchases",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| search ProviderName = \"$ProviderName$\" ChargeCategory = \"Purchase\" CommitmentDiscountId = * \n| eval ChargePeriodStart = strptime(ChargePeriodStart, \"%Y-%m-%d %H:%M:%S\") \n| eval ChargePeriodEnd = strptime(ChargePeriodEnd, \"%Y-%m-%d %H:%M:%S\") \n| stats min(ChargePeriodStart) AS ChargePeriodStart,\n    max(ChargePeriodEnd) AS ChargePeriodEnd,\n    sum(BilledCost) AS TotalBilledCost BY ProviderName, BillingAccountId, CommitmentDiscountId, CommitmentDiscountType, ChargeFrequency \n| eval ChargePeriodStart = strftime(ChargePeriodStart, \"%Y-%m-%d %H:%M:%S\") \n| eval ChargePeriodEnd = strftime(ChargePeriodEnd, \"%Y-%m-%d %H:%M:%S\")"
			},
			"type": "ds.chain"
		},
		"ds_AOIyDGLX": {
			"name": "Table - Analyze service costs month over month",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| search ProviderName = \"$ProviderName$\" \n| stats sum(sumEffectiveCost) AS TotalEffectiveCost BY ProviderName, ServiceName \n| sort -TotalEffectiveCost"
			},
			"type": "ds.chain"
		},
		"ds_HOisVZBX": {
			"name": "Table - Report refunds by subaccount within a billing period",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| search ProviderName=$ProviderName$ \n| stats sum(sumBilledCost) AS TotalBilledCost \n    BY ProviderName, BillingAccountId, SubAccountId, SubAccountName, ServiceCategory, ChargeCategory\n| sort -TotalBilledCost"
			},
			"type": "ds.chain"
		},
		"ds_J4evhrdt": {
			"name": "Provider Name",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| dedup ProviderName \n| table ProviderName"
			},
			"type": "ds.chain"
		},
		"ds_NolQgnb3": {
			"name": "Column - Analyze service costs month over month",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| search ProviderName=\"$ProviderName$\"\n| timechart span=1mon eval(round(sum(sumEffectiveCost),2)) as TotalEffectiveCost by ServiceName\n| addtotals label=Total"
			},
			"type": "ds.chain"
		},
		"ds_QLm6ljl9": {
			"name": "Donat - Report costs by service category",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| search ProviderName = \"$ProviderName$\"\n| stats sum(sumBilledCost) AS TotalBilledCost \n    BY ServiceCategory \n| sort -TotalBilledCost"
			},
			"type": "ds.chain"
		},
		"ds_SOkCeoDE": {
			"name": "Column - Report application cost month over month",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| rex field=Tags max_match=0 \"\\'application\\':\\s*\\'(?<Application>[^\\']+)\\'\"\n| search ProviderName=\"$ProviderName$\" EffectiveCost > 0 Application=*\n| timechart span=1mon eval(round(sum(sumEffectiveCost),2)) as TotalEffectiveCost by Application \n| sort -TotalEffectiveCost"
			},
			"type": "ds.chain"
		},
		"ds_UdK3QLrI": {
			"name": "Table - Analyze service costs by region",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| search ProviderName=\"$ProviderName$\"\n| stats sum(sumEffectiveCost) AS TotalEffectiveCost BY ProviderName, RegionId, RegionName \n| sort -TotalEffectiveCost"
			},
			"type": "ds.chain"
		},
		"ds_VY2da9PN": {
			"name": "Service Category",
			"options": {
				"extend": "ds_DoQHZaPT",
				"query": "| search ProviderName=\"$ProviderName$\" \n| eval ServiceCategory = if(ServiceCategory==\"\", \"No ServiceCategory\", ServiceCategory) \n| dedup ServiceCategory \n| table ServiceCategory"
			},
			"type": "ds.chain"
		},
		"ds_VpkoAL1R": {
			"name": "Table - Determine Effective Savings Rate by Service",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| search ProviderName = \"$ProviderName$\" EffectiveCost > 0 \n| eval ESROverList = (ListCost - EffectiveCost) / ListCost,\n    ESROverContract = (ContractedUnitPrice - EffectiveCost) / ContractedUnitPrice \n| table ProviderName, ServiceCategory, ContractedUnitPrice, PricingQuantity, EffectiveCost, ESROverList, ESROverContract"
			},
			"type": "ds.chain"
		},
		"ds_Xp8oEsQD": {
			"name": "Donut - Analyze service costs by region",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| stats sum(sumEffectiveCost) AS TotalEffectiveCost BY RegionId \n| sort ChargePeriodStart, -TotalEffectiveCost"
			},
			"type": "ds.chain"
		},
		"ds_YAvFnFcJ": {
			"name": "Table - Analyze the different metered costs for a particular SKU",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| search ProviderName=$ProviderName$\n| stats sum(PricingQuantity) AS TotalPricingQuantity,\n    sum(ListCost) AS TotalListCost,\n    sum(sumEffectiveCost) AS TotalEffectiveCost \n    BY ProviderName, ChargePeriodStart, ChargePeriodEnd, SkuId, SkuPriceId, PricingUnit, ListUnitPrice \n| sort ChargePeriodStart \n| head 100"
			},
			"type": "ds.chain"
		},
		"ds_aUkjWsOF": {
			"name": "SingleValue - Analyze tag coverage",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| search ProviderName=\"$ProviderName$\"\n`focus_tag`\n`focus_tag_timetable`\n| eval tag_perc = case(isnull(tag_perc), 0, 1=1, tag_perc)\n| stats latest(tag_perc) as tag_perc by _time\n| where tag_perc like(\"%\")"
			},
			"type": "ds.chain"
		},
		"ds_eE9nmwJi": {
			"name": "Table - Analyze capacity reservations on compute costs",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| search ServiceCategory = \"Compute\"\n| eval Status = case(\n    isnotnull(CapacityReservationId) AND CapacityReservationStatus == \"Unused\", \"Unused Capacity Reservation\",\n    isnotnull(CapacityReservationId) AND CapacityReservationStatus == \"Used\", \"Compute using Capacity Reservation\",\n    true(), \"Compute without Capacity Reservation\"\n)\n| stats sum(sumBilledCost) AS TotalBilledCost,\n        sum(sumEffectiveCost) AS TotalEffectiveCost \n    BY Status, ProviderName, BillingAccountId"
			},
			"type": "ds.chain"
		},
		"ds_fnx58zkT": {
			"name": "Table - Report costs by service category",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| search ProviderName = \"$ProviderName$\" \n| stats sum(sumBilledCost) AS TotalBilledCost \n    BY ProviderName, BillingCurrency, BillingPeriodStart, ServiceCategory \n| sort -TotalBilledCost"
			},
			"type": "ds.chain"
		},
		"ds_hl67qYgO": {
			"name": "Column - Analyze costs by service name",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| stats sum(sumBilledCost) AS TotalBilledCost,  sum(EffectiveCost) AS TotalEffectiveCost BY ServiceName \n| sort -TotalBilledCost\n| head 10"
			},
			"type": "ds.chain"
		},
		"ds_lS0IkD6t": {
			"name": "SingleValue - Report refunds by subaccount within a billing period",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| search ProviderName=$ProviderName$\n| stats sum(sumBilledCost) AS BilledCost"
			},
			"type": "ds.chain"
		},
		"ds_n6LtddhB": {
			"name": "Table - Report costs by service category and subcategory",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| search ProviderName=$ProviderName$\n| eval ServiceSubcategory = if(isnull(ServiceSubcategory), \"n/a\", ServiceSubcategory)\n| stats sum(sumBilledCost) AS TotalBilledCost \n    BY ProviderName, BillingCurrency, BillingPeriodStart, ServiceCategory, ServiceSubcategory \n| sort -TotalBilledCost\n"
			},
			"type": "ds.chain"
		},
		"ds_njkjlc6w": {
			"name": "Column - Report spending across billing periods for a provider by service category 3",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| search ProviderName = $ProviderName$\n| stats sum(sumBilledCost) AS TotalBilledCost BY ServiceCategory\n| sort -TotalBilledCost"
			},
			"type": "ds.chain"
		},
		"ds_qLyntruR": {
			"name": "Table - Report spending across billing periods for a provider by service category",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| search ProviderName = $ProviderName$ \n| stats sum(sumBilledCost) AS TotalBilledCost \n    BY ProviderName, BillingAccountName, BillingAccountId, BillingCurrency, BillingPeriodStart, ServiceCategory, ServiceName \n| sort -TotalBilledCost"
			},
			"type": "ds.chain"
		},
		"ds_wdFdquhF": {
			"name": "Table - Analyze costs of components of a resource",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| search ProviderName = \"$ProviderName$\" ResourceId = * \n| stats sum(sumEffectiveCost) AS TotalEffectiveCost BY ResourceId, ResourceName, ResourceType, ChargeDescription, SkuId \n| sort -TotalEffectiveCost"
			},
			"type": "ds.chain"
		},
		"ds_wz8w0q4N": {
			"name": "Table - Report effective cost of compute",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| search ProviderName = \"$ProviderName$\" ServiceCategory = \"Compute\" \n| stats sum(sumEffectiveCost) AS TotalEffectiveCost \n    BY  CommitmentDiscountType, ServiceName, ProviderName, SubAccountId, SubAccountName, BillingPeriodStart\n| sort -TotalEffectiveCost"
			},
			"type": "ds.chain"
		},
		"ds_yT4i6GXs": {
			"name": "Table - Report recurring charges for commitment-based discounts over a period",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| search ChargeFrequency = \"Recurring\" CommitmentDiscountId=\"*\" \n| stats sum(BilledCost) AS TotalBilledCost BY BillingPeriodStart, CommitmentDiscountId, CommitmentDiscountCategory, CommitmentDiscountType, ChargeFrequency"
			},
			"type": "ds.chain"
		},
		"ds_yrY5Lx8F": {
			"name": "Table - Identify which provider versions your datasets have been generated with",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| dedup ProviderName \n| fields ProviderName, ProviderVersion \n| search ProviderName=$ProviderName$ \n| table ProviderName, ProviderVersion"
			},
			"type": "ds.chain"
		},
		"ds_yzDHojCx": {
			"name": "Table - Identify unused capacity reservations",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| search CapacityReservationStatus = \"Unused\"\n| stats sum(BilledCost) AS TotalBilledCost,\n        sum(EffectiveCost) AS TotalEffectiveCost \n    BY ProviderName, BillingAccountId, CapacityReservationId, CapacityReservationStatus"
			},
			"type": "ds.chain"
		},
		"ds_zdp9lgRW": {
			"name": "Table - Report service costs by providers subaccount",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| search ProviderName = \"$ProviderName$\" SubAccountId = *\n| stats sum(sumEffectiveCost) AS TotalEffectiveCost \n    BY ProviderName, ServiceName, SubAccountId, SubAccountName\n| sort -TotalEffectiveCost"
			},
			"type": "ds.chain"
		},
		"ds_5GCpDkN0": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| search ProviderName=\"$ProviderName$\" \n`focus_tag` \n| stats max(with_tag) as with_tag min(no_tag) as no_tag dc(ResourceId) as total by ResourceId ServiceCategory \n| stats sum(with_tag) as with_tag sum(no_tag) as no_tag sum(total) as total by ServiceCategory \n| eval with_perc = if(isnull(round(100*with_tag/total,2)), 0, round(100*with_tag/total,2)) \n| fields ServiceCategory with_perc"
			},
			"name": "Column - Analyze tag coverage"
		},
		"ds_8mFavfsn": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_iBQpByei",
				"query": "| rex field=Tags max_match=0 \"\\'application\\':\\s*\\'(?<Application>[^\\']+)\\'\" \n| search ProviderName=\"*\" EffectiveCost > 0 Application=*\n| eval BillingPeriodStart = strptime(BillingPeriodStart, \"%Y-%m-%d %H:%M:%S\") \n| eval Month = strftime(BillingPeriodStart, \"%Y-%m\") \n| stats sum(EffectiveCost) AS TotalEffectiveCost BY Month Application \n| eval TotalEffectiveCost = round(TotalEffectiveCost,2) \n| sort -TotalEffectiveCost"
			},
			"name": "Table - Report application cost month over month"
		},
		"ds_iBQpByei": {
			"type": "ds.search",
			"options": {
				"query": "| `focus_base_search`"
			},
			"name": "Base Search"
		}
	},
